#include <string>
#include <vector>

#include "web/UiAssetsData.hpp"  // generated by cmake/EmbedFiles.cmake from src/web/ui/*
#include "web/WebServer.hpp"

namespace reforce::web {

const UiAsset* findUiAsset(const std::string& name) {
    static const std::vector<UiAsset> assets = [] {
        std::vector<UiAsset> v;
        for (const auto& f : generated::kUiAssets) v.push_back({f.name, f.data, f.size});
        return v;
    }();
    for (const auto& a : assets)
        if (name == a.name) return &a;
    return nullptr;
}

std::vector<std::string> uiAssetNames() {
    std::vector<std::string> out;
    for (const auto& f : generated::kUiAssets) out.push_back(f.name);
    return out;
}

}  // namespace reforce::web
